// readAndCheckFrameHeader reads and validates a frame header from the underlying reader.
// It returns enhanced error information including frame type, stream ID, and flags when errors occur.
func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}
	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Validate frame size
	if fh.Length > fr.maxReadSize {
		return fh, connError{
			Description: fmt.Sprintf("frame too large: %d bytes exceeds maximum %d", fh.Length, fr.maxReadSize),
			FrameType:   fh.Type,
			StreamID:    fh.StreamID,
			Flags:       fh.Flags,
		}
	}

	return fh, nil
}

