// WithStreamOptions sets options specifically for streaming RPC calls.
// This allows fine-grained control over streaming call behavior without affecting unary calls.
func WithStreamOptions(opts ...StreamOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		for _, opt := range opts {
			opt.F(o, di)
		}
	}}
}

// WithStreamRecvTimeout sets the receive timeout specifically for streaming calls.
// This timeout applies to each individual Recv() operation on a stream.
// Note: This is a placeholder that doesn't modify client options as streaming timeouts
// are typically configured at the transport or protocol level.
func WithStreamRecvTimeout(d time.Duration) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.WriteString("WithStreamRecvTimeout()")
		// Streaming receive timeout configuration placeholder
		_ = d
	}}
}

// WithStreamSendTimeout sets the send timeout specifically for streaming calls.
// This timeout applies to each individual Send() operation on a stream.
// Note: This is a placeholder that doesn't modify client options as streaming timeouts
// are typically configured at the transport or protocol level.
func WithStreamSendTimeout(d time.Duration) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.WriteString("WithStreamSendTimeout()")
		// Streaming send timeout configuration placeholder
		_ = d
	}}
}

// WithStreamMiddleware adds a middleware that applies to both send and receive operations.
// The middleware will be applied to all streaming calls made by this client.
func WithStreamMiddleware(mw endpoint.Middleware) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.WriteString("WithStreamMiddleware()")
		// Add to general middleware builders
		o.MWBs = append(o.MWBs, func(ctx *endpoint.Context) endpoint.Endpoint {
			return mw(ctx.GetEndpoint())
		})
	}}
}

// WithStreamRecvMiddleware adds a middleware specifically for stream receive operations.
// This middleware will be invoked for each Recv() call on a stream.
func WithStreamRecvMiddleware(mw endpoint.Middleware) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.WriteString("WithStreamRecvMiddleware()")
		// Streaming-specific recv middleware placeholder
		_ = mw
	}}
