func WithStreamSendMiddleware(mw endpoint.Middleware) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.WriteString("WithStreamSendMiddleware()")
		// Streaming-specific send middleware placeholder
		_ = mw
	}}
}

// WithStreamMiddlewareBuilder adds a middleware builder that applies to both send and receive.
// The builder creates a middleware based on the call context.
func WithStreamMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) StreamOption {
	return StreamOption{F: func(o *client.Options, di *utils.Slice) {
		di.WriteString("WithStreamMiddlewareBuilder()")
