// Package streamcall contains call-level options for streaming RPC calls.
// It provides Option type that wraps callopt.Option for use with StreamClient interface.
package streamcall

import (
	"strings"

	"github.com/cloudwego/kitex/client/callopt"
)

// Option is a call-level option for streaming RPC calls.
// It wraps callopt.Option to provide a compatible interface for StreamClient methods.
type Option struct {
	f func(*callopt.CallOptions, *strings.Builder)
}

// GetCallOption returns the underlying callopt.Option.
// This allows streamcall.Option to be used where callopt.Option is required.
func (o Option) GetCallOption() callopt.Option {
	return callopt.NewOption(o.f)
}

// ConvertOptionFrom converts a callopt.Option to a streamcall.Option.
// This is useful for reusing existing call options with StreamClient interface.
// Note: Not all callopt.Option(s) may work correctly with streaming calls.
func ConvertOptionFrom(opt callopt.Option) Option {
	return Option{f: opt.F()}
}

// GetCallOptions converts a slice of streamcall.Option to callopt.Option slice.
func GetCallOptions(opts []Option) []callopt.Option {
	result := make([]callopt.Option, 0, len(opts))
	for _, opt := range opts {
		result = append(result, opt.GetCallOption())
	}
	return result
}

